        "html": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"UTF-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n        <title>Document</title>\r\n        <link rel=\"stylesheet\" href=\"./style.css\" />\r\n    </head>\r\n    <body>\r\n        <form action=\"\">\r\n            <table width=\"300px\" cellspacing=\"0\" cellpadding=\"5\">\r\n                <tr>\r\n                    <td><label for=\"username\">Username:</label></td>\r\n                    <td>\r\n                        <input type=\"text\" name=\"name\" id=\"username\" />\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td><label for=\"password\">Password:</label></td>\r\n                    <td>\r\n                        <input type=\"password\" name=\"password\" id=\"password\" />\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td>\r\n                        <label for=\"city\">City of Employment:</label>\r\n                    </td>\r\n                    <td>\r\n                        <input type=\"text\" name=\"city\" id=\"city\" />\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td><label for=\"server\">Web server:</label></td>\r\n                    <td>\r\n                        <select name=\"server\" id=\"server\">\r\n                            <option value=\"\">--Choose a server--</option>\r\n                            <option value=\"0\">Server Trái Đất</option>\r\n                            <option value=\"1\">Server HTMLOL</option>\r\n                        </select>\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td rowspan=\"4\">\r\n                        <label>Please specify your role:</label>\r\n                    </td>\r\n                    <td>\r\n                        <label\r\n                            ><input\r\n                                type=\"radio\"\r\n                                name=\"specify\"\r\n                                value=\"0\"\r\n                            />Admin</label\r\n                        >\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td>\r\n                        <label\r\n                            ><input\r\n                                type=\"radio\"\r\n                                name=\"specify\"\r\n                                value=\"0\"\r\n                            />Engineer</label\r\n                        >\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td>\r\n                        <label\r\n                            ><input\r\n                                type=\"radio\"\r\n                                name=\"specify\"\r\n                                value=\"0\"\r\n                            />Manager</label\r\n                        >\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td>\r\n                        <label\r\n                            ><input\r\n                                type=\"radio\"\r\n                                name=\"specify\"\r\n                                value=\"0\"\r\n                            />Guest</label\r\n                        >\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td rowspan=\"3\">\r\n                        <label>Single Sign-on to the following:</label>\r\n                    </td>\r\n                    <td>\r\n                        <label\r\n                            ><input\r\n                                type=\"checkbox\"\r\n                                name=\"sign-on\"\r\n                                value=\"0\"\r\n                            />Mail</label\r\n                        >\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td>\r\n                        <label\r\n                            ><input\r\n                                type=\"checkbox\"\r\n                                name=\"sign-on\"\r\n                                value=\"0\"\r\n                            />Payroll</label\r\n                        >\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td>\r\n                        <label>\r\n                            <input\r\n                                type=\"checkbox\"\r\n                                name=\"sign-on\"\r\n                                value=\"0\"\r\n                            />Self-service</label\r\n                        >\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n            <button type=\"submit\">Login</button>\r\n            <button type=\"reset\">Reset</button>\r\n        </form>\r\n    </body>\r\n</html>\r\n",
