        "css": "* {\r\n    padding: 0;\r\n    margin: 0;\r\n    box-sizing: border-box;\r\n}\r\n\r\nbody {\r\n    /* display: flex; */\r\n    justify-content: center;\r\n}\r\n\r\nheader {\r\n    margin-top: 20px;\r\n    text-align: center;\r\n}\r\n\r\nheader h1 {\r\n    font-size: 40px;\r\n}\r\n\r\nheader nav {\r\n    margin-top: 10px;\r\n}\r\n\r\nnav ul {\r\n    display: block;\r\n    list-style-type: none;\r\n}\r\n\r\nnav ul li {\r\n    display: inline-block;\r\n}\r\n\r\nnav ul li:hover a {\r\n    color: #fff;\r\n    background-color: #29378e;\r\n}\r\n\r\nnav ul a {\r\n    color: #000;\r\n    display: block;\r\n    padding: 15px 25px;\r\n    text-decoration: none;\r\n}\r\n\r\n.main {\r\n    display: flex;\r\n    margin-top: 30px;\r\n    justify-content: center;\r\n}\r\n\r\n.main__item {\r\n    width: 200px;\r\n    position: relative;\r\n}\r\n\r\n.main__img img {\r\n    display: block;\r\n    width: 100%;\r\n}\r\n\r\n.main__info {\r\n    text-align: center;\r\n}\r\n\r\n.main__info--rate {\r\n    margin: 15px 0;\r\n}\r\n\r\n.main__info--rate i {\r\n    font-size: 10px;\r\n    cursor: pointer;\r\n}\r\n\r\n.main__info--name {\r\n    margin: 10px 0;\r\n}\r\n\r\n.main__info--price {\r\n    font-weight: bold;\r\n}\r\n\r\n.action-hover {\r\n    width: 100%;\r\n    bottom: 130px;\r\n    opacity: 0;\r\n    text-align: center;\r\n    position: absolute;\r\n    transition: linear 0.3s;\r\n}\r\n\r\n.action-hover .action__icon {\r\n    display: flex;\r\n    font-size: 10px;\r\n    justify-content: center;\r\n}\r\n\r\n.action__heart,\r\n.action__transfer,\r\n.action__eye {\r\n    color: #fff;\r\n    margin: 0 5px;\r\n    padding: 15px 15px;\r\n    background-color: #28388d;\r\n}\r\n\r\n.action__heart:hover,\r\n.action__transfer:hover,\r\n.action__eye:hover,\r\n.action-hover button:hover {\r\n    opacity: 0.9;\r\n    cursor: pointer;\r\n}\r\n\r\n.action-hover button {\r\n    border: none;\r\n    color: #fff;\r\n    margin-top: 10px;\r\n    padding: 15px 40px;\r\n    background-color: #28388d;\r\n}\r\n\r\n.main__item:hover .action-hover {\r\n    opacity: 1;\r\n    display: block;\r\n    bottom: 100px;\r\n}\r\n\n",
