        "css": "* {\r\n    margin: 0;\r\n    padding: 0;\r\n    box-sizing: border-box;\r\n    outline: none;\r\n}\r\n\r\n:root {\r\n    --primary-color: #f7e165;\r\n    --font-heading: \"Space Grotesk\", sans-serif;\r\n    --font-content: \"Inter\", sans-serif;\r\n}\r\n\r\n.container {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    width: 1200px;\r\n    margin: 20px auto;\r\n}\r\n\r\n.product {\r\n    width: calc((100% / 3) - 60px);\r\n    margin: 30px 30px;\r\n    background: center / cover;\r\n    border: 1px solid #ccc;\r\n    padding: 30px;\r\n    position: relative;\r\n    height: 300px;\r\n    overflow: hidden;\r\n}\r\n\r\n.product__icon {\r\n    font-size: 40px;\r\n    color: var(--primary-color);\r\n    margin-bottom: 20px;\r\n    transition: 0.2s linear;\r\n    transition-delay: 0.2s;\r\n}\r\n\r\n.product__animation {\r\n    color: #000;\r\n    position: absolute;\r\n    top: 100px;\r\n    transition: top 0.5s ease-out;\r\n    transition-delay: 0.1s;\r\n}\r\n\r\n.product__heading h2 {\r\n    width: 95%;\r\n    font-family: var(--font-heading);\r\n}\r\n\r\n.product__dsc {\r\n    margin: 10px 0;\r\n}\r\n\r\n.product__btn {\r\n    display: flex;\r\n    align-items: center;\r\n    position: absolute;\r\n    margin-top: 100px;\r\n    color: #fff;\r\n    cursor: pointer;\r\n}\r\n\r\n.product__more-icon {\r\n    font-size: 15px;\r\n    line-height: 30px;\r\n    text-align: center;\r\n    margin-left: 10px;\r\n    width: 30px;\r\n    height: 30px;\r\n    border: 1px solid #fff;\r\n    border-radius: 50%;\r\n}\r\n\r\n.product__more-icon:hover {\r\n    color: #000;\r\n    background-color: #fff;\r\n}\r\n\r\n.product:hover {\r\n    background: url(\"./img/geike-verniers-aqjPwQ2Gne8-unsplash.jpg\") no-repeat\r\n        center / cover;\r\n}\r\n\r\n.product:hover .product__icon {\r\n    font-size: 10px;\r\n    visibility: hidden;\r\n}\r\n\r\n.product:hover .product__animation {\r\n    top: 30px;\r\n    color: #fff;\r\n}\r\n\n",
